// This file is generated by AI.

// 行级差异的断言 (文本预处理"本步改了什么"用的就是它)。
//
// 用法上只有一件事要记住: `line` 取的是**改动后**文本的行号 —— 删除没有对应的新行,
// 锚在它被删掉的位置, 这样结果可以直接当 Monaco 装饰的行号用。

import { describe, expect, it } from 'vitest';

import { diffLines } from '../src/editor/line-diff';

describe('diffLines', () => {
  it('完全相同时不产生改动', () => {
    expect(diffLines('a\nb\nc', 'a\nb\nc')).toEqual([]);
  });

  it('末尾新增一行', () => {
    expect(diffLines('a\nb', 'a\nb\nc')).toEqual([{ line: 3, kind: 'A' }]);
  });

  it('中间插入一行, 后面的行不算改动', () => {
    expect(diffLines('a\nc', 'a\nb\nc')).toEqual([{ line: 2, kind: 'A' }]);
  });

  it('删除一行, 锚在它被删掉的位置', () => {
    expect(diffLines('a\nb\nc', 'a\nc')).toEqual([{ line: 2, kind: 'D' }]);
  });

  it('改写一行', () => {
    expect(diffLines('a\nb\nc', 'a\nB\nc')).toEqual([{ line: 2, kind: 'M' }]);
  });

  it('一行断成三行: 首行算改写, 其余算新增', () => {
    expect(diffLines('a', 'a1\na2\na3')).toEqual([
      { line: 1, kind: 'M' },
      { line: 2, kind: 'A' },
      { line: 3, kind: 'A' },
    ]);
  });

  it('整段替换 (两侧都不止一行) 按位置配对', () => {
    expect(diffLines('a\nb', 'x\ny\nz')).toEqual([
      { line: 1, kind: 'M' },
      { line: 2, kind: 'M' },
      { line: 3, kind: 'A' },
    ]);
  });

  it('删得比加得多时多出来的算删除', () => {
    expect(diffLines('a\nb\nc\nd', 'x\ny')).toEqual([
      { line: 1, kind: 'M' },
      { line: 2, kind: 'M' },
      { line: 3, kind: 'D' },
    ]);
  });

  it('给行首加前缀只算改写 (文本预处理第 3 步配说话者)', () => {
    const before = '; 原句\n%:你好。\n:今天天气不错。';
    const after = '; 原句\n1-小明:你好。\n:今天天气不错。';
    expect(diffLines(before, after)).toEqual([{ line: 2, kind: 'M' }]);
  });

  it('空文档到有内容时全部算新增', () => {
    expect(diffLines('', 'a\nb')).toEqual([
      { line: 1, kind: 'A' },
      { line: 2, kind: 'A' },
    ]);
  });

  it('内容清空时全部算删除, 锚在第一行', () => {
    expect(diffLines('a\nb', '')).toEqual([{ line: 1, kind: 'D' }]);
  });

  it('公共前后缀不参与对齐 (中间那一行改写)', () => {
    const before = ['head', 'x', 'tail'].join('\n');
    const after = ['head', 'y', 'tail'].join('\n');
    expect(diffLines(before, after)).toEqual([{ line: 2, kind: 'M' }]);
  });

  it('超出 LCS 预算的长文退化成整体按位置配对, 且不会漏行', () => {
    const before = Array.from({ length: 600 }, (_, i) => `旧 ${i}`).join('\n');
    const after = Array.from({ length: 600 }, (_, i) => `新 ${i}`).join('\n');
    const changes = diffLines(before, after);
    expect(changes).toHaveLength(600);
    expect(changes.every((c) => c.kind === 'M')).toBe(true);
    expect(changes[599]).toEqual({ line: 600, kind: 'M' });
  });

  it('行号随对齐结果偏移 (前面插入后再改写)', () => {
    const changes = diffLines('a\nb\nc', 'x\na\nB\nc');
    expect(changes).toEqual([
      { line: 1, kind: 'A' },
      { line: 3, kind: 'M' },
    ]);
  });
});
